pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Reward bins that have more space left
    if bin_residual > 50 {
        score += 1.0;
    } else if bin_residual > 20 {
        score += 0.5;
    }

    // Penalize creating new bins unless necessary
    if open_bins_count == 0 && fitting_bins_count == 0 {
        score -= 2.0;
    } else if open_bins_count > 0 && fitting_bins_count == 0 {
        score -= 0.5 * (open_bins_count as f64);
    }

    // Reward bins that can fit the next item
    if post_residual >= next_item_size {
        score += 1.0;
    } else if post_residual < next_item_size && fitting_bins_count > 0 {
        score += 0.5 * (fitting_bins_count as f64);
    }

    // Penalize bins with very low residual space
    if bin_residual < 10 {
        score -= 2.0;
    } else if bin_residual < 30 {
        score -= 1.0;
    }

    // Reward bins that have a higher mean residual
    if mean_residual > 50 {
        score += 0.5 * (mean_residual / 50.0);
    }

    // Penalize late steps in the process
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.8 {
        score -= 1.5 * (progress - 0.8);
    }

    // Additional reward for bins with a better fit ratio
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    if fit_ratio > 0.75 {
        score += 0.25 * (fit_ratio - 0.75);
    } else if fit_ratio > 0.5 {
        score += 0.1 * (fit_ratio - 0.5);
    }

    score
}

